// Some portions generated by Codex
const { test, expect } = require('@playwright/test');
const { deleteRepository, memoryRepositoryConfiguration, repositoryPageUrl, serverBaseUrl,
    uniqueRepositoryId, waitForRoute, chooseGraphView } = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('graph-update-order');
const EX = 'http://example.org/update-order/';

test.beforeAll(async ({ request }) => {
    const url = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(url, { headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph update ordering') });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${url}/statements`, { headers: { 'Content-Type': 'text/turtle' },
        data: `@prefix ex: <${EX}> . ex:alice ex:knows ex:bob . ex:bob ex:worksFor ex:acme . ex:acme ex:location ex:oslo .` });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => { await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID); });

test('Find receives its shortcut in the same task and leaves editable shortcuts alone', async ({ page }) => {
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    const find = explorer.getByRole('combobox', { name: /Find a node/ });
    await expect(find).toBeVisible();
    const focusedImmediately = await page.evaluate(() => {
        document.dispatchEvent(new KeyboardEvent('keydown', { key: '/', bubbles: true, cancelable: true }));
        return document.activeElement === document.querySelector('.graph-explorer input[role="combobox"]');
    });
    expect(focusedImmediately).toBe(true);
    await page.keyboard.type('Alice');
    await expect(find).toHaveValue('Alice');
    await page.keyboard.press('/');
    await expect(find).toHaveValue('Alice/');

    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    const query = explorer.locator('#sparql');
    await query.fill('editable');
    await page.keyboard.press('/');
    await expect(query).toBeFocused();
    await expect(query).toHaveValue('editable/');
    await explorer.getByRole('button', { name: 'Close query editor' }).click();
    await chooseGraphView(explorer, 'table');
    await page.keyboard.press('/');
    await expect(find).toBeFocused();
    await page.keyboard.type('Bob');
    await expect(find).toHaveValue('Bob');
});

for (const complete of [false, true]) {
  test(`a queued ${complete ? 'final' : 'intermediate'} layout frame preserves a replacing query`, async ({ page }, testInfo) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    // Control only the frame scheduler, through its public browser API. The real component, query transport and
    // React update queue run normally. The answer marker puts the held old frame after the new graph is queued,
    // before React commits it: the ordering that a slow/busy browser can otherwise reach nondeterministically.
    await page.evaluate(complete => {
        const request = window.requestAnimationFrame.bind(window);
        const cancel = window.cancelAnimationFrame.bind(window);
        const mark = performance.mark.bind(performance);
        const frames = new Map();
        let id = 0;
        const trace = [];
        window.requestAnimationFrame = callback => {
            frames.set(--id, { callback, scheduled: performance.now() });
            return id;
        };
        window.cancelAnimationFrame = key => { frames.delete(key); };
        const control = window.graphFrameOrder = {
            armed: false, trace,
            pending: () => frames.size,
            restore: () => {
                window.requestAnimationFrame = request;
                window.cancelAnimationFrame = cancel;
                performance.mark = mark;
                for (const { callback } of frames.values()) request(callback);
                frames.clear();
            }
        };
        performance.mark = (name, options) => {
            const result = mark(name, options);
            if (name === 'graph-explorer:answer-shown' && control.armed) {
                control.armed = false;
                queueMicrotask(() => {
                    const held = [...frames.values()];
                    frames.clear();
                    trace.push({ event: 'old-frame-after-answer', callbacks: held.length,
                        before: document.querySelector('.graph-stats')?.textContent });
                    for (const { callback, scheduled } of held) callback(scheduled + (complete ? 1000 : 16));
                });
            }
            return result;
        };
    }, complete);
    try {
        await explorer.getByRole('button', { name: 'Load 100 statements' }).evaluate(button => button.click());
        await expect(explorer.locator('.graph-node')).toHaveCount(4);
        await expect.poll(() => page.evaluate(() => window.graphFrameOrder.pending())).toBeGreaterThan(0);
        await explorer.getByRole('button', { name: 'Query editor', exact: true }).evaluate(button => button.click());
        await explorer.locator('#sparql').fill(`CONSTRUCT { <${EX}alice> <${EX}knows> <${EX}bob> } WHERE {}`);
        await page.evaluate(() => { window.graphFrameOrder.armed = true; });
        await explorer.getByRole('button', { name: 'Run query' }).evaluate(button => button.click());
        await expect.poll(() => page.evaluate(() => window.graphFrameOrder.trace.length)).toBe(1);
        await expect(explorer.locator('.graph-node')).toHaveCount(2);
        await expect(explorer.locator('.graph-stats')).toHaveText('2 nodes · 1 link');
    } finally {
        const trace = await page.evaluate(() => {
            const control = window.graphFrameOrder;
            const trace = control.trace;
            control.restore();
            return trace;
        });
        await testInfo.attach('frame-order.json', { body: JSON.stringify(trace, null, 2), contentType: 'application/json' });
    }
  });
}

/** Hold real component frames while ordinary DOM actions take ownership of the view or cancel the layout. */
async function holdFrames(page) {
    await page.evaluate(() => {
        const request = window.requestAnimationFrame.bind(window);
        const cancel = window.cancelAnimationFrame.bind(window);
        const frames = new Map();
        let id = 0;
        const trace = [];
        window.requestAnimationFrame = callback => {
            frames.set(--id, { callback, scheduled: performance.now() });
            return id;
        };
        window.cancelAnimationFrame = key => {
            if (frames.delete(key)) trace.push({ event: 'cancel', key });
        };
        window.graphHeldFrames = {
            pending: () => frames.size,
            flush: () => {
                const held = [...frames.entries()];
                frames.clear();
                for (const [key, { callback, scheduled }] of held) {
                    trace.push({ event: 'frame', key });
                    callback(scheduled + 1000);
                }
            },
            restore: () => {
                window.requestAnimationFrame = request;
                window.cancelAnimationFrame = cancel;
                for (const { callback } of frames.values()) request(callback);
                frames.clear();
                return trace;
            }
        };
    });
}

async function releaseFrames(page, testInfo) {
    const trace = await page.evaluate(() => window.graphHeldFrames.restore());
    await testInfo.attach('held-frames.json', { body: JSON.stringify(trace, null, 2), contentType: 'application/json' });
}

test('a held layout frame preserves a newer user zoom', async ({ page }, testInfo) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await holdFrames(page);
    try {
        await explorer.getByRole('button', { name: 'Load 100 statements' }).evaluate(button => button.click());
        await expect(explorer.locator('.graph-node')).toHaveCount(4);
        await expect.poll(() => page.evaluate(() => window.graphHeldFrames.pending())).toBeGreaterThan(0);
        const layer = explorer.locator('svg.graph-canvas > g[transform]');
        const before = await layer.getAttribute('transform');
        await explorer.getByRole('button', { name: 'Zoom in', exact: true }).evaluate(button => button.click());
        await expect(layer).not.toHaveAttribute('transform', before);
        const zoomed = await layer.getAttribute('transform');
        await page.evaluate(() => window.graphHeldFrames.flush());
        await expect(layer).toHaveAttribute('transform', zoomed);
        await expect(explorer.locator('.graph-node')).toHaveCount(4);
    } finally {
        await releaseFrames(page, testInfo);
    }
});

test('pinning cancels held layout movement and route disposal cancels its remaining frames', async ({ page }, testInfo) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    await holdFrames(page);
    try {
        await explorer.getByRole('button', { name: 'Load 100 statements' }).evaluate(button => button.click());
        await expect(explorer.locator('.graph-node')).toHaveCount(4);
        await expect.poll(() => page.evaluate(() => window.graphHeldFrames.pending())).toBeGreaterThan(0);
        const node = explorer.locator('.graph-node').first();
        await node.evaluate(element => element.dispatchEvent(new MouseEvent('click', { bubbles: true })));
        await explorer.getByRole('button', { name: 'Pin in place', exact: true }).evaluate(button => button.click());
        await expect(node).toHaveClass(/is-pinned/);
        const pinnedPosition = await node.getAttribute('transform');
        await page.evaluate(() => window.graphHeldFrames.flush());
        await expect(node).toHaveAttribute('transform', pinnedPosition);
        await expect(node).toHaveClass(/is-pinned/);

        await page.evaluate(url => window.workbench.router.navigate(url, { history: 'push' }),
            repositoryPageUrl(REPOSITORY_ID, 'summary'));
        await waitForRoute(page, 'summary');
        await page.evaluate(() => window.graphHeldFrames.flush());
        await expect(explorer).toHaveCount(0);
        expect(errors).toEqual([]);
    } finally {
        await releaseFrames(page, testInfo);
    }
});
